class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        int best = Integer.MAX_VALUE;

        for (int left = 0; left < n; left++) {
            int sum = 0;
            for (int right = left; right < n; right++) {
                sum += nums[right];
                if (sum >= target) {
                    best = Math.min(best, right - left + 1);
                    break;   // 再往后加只会更长，没必要继续
                }
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        int best = Integer.MAX_VALUE;
        for (int left = 0; left < n; left++) {
            int want = prefix[left] + target;
            // 在 [left+1, n] 里找第一个 >= want 的下标
            int pos = lowerBound(prefix, left + 1, n, want);
            if (pos <= n) {
                best = Math.min(best, pos - left);
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }

    // 返回 [lo, hi] 中第一个 >= want 的下标，找不到返回 hi+1
    private int lowerBound(int[] arr, int lo, int hi, int want) {
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] < want) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        int left = 0, sum = 0;
        int best = Integer.MAX_VALUE;

        for (int right = 0; right < n; right++) {
            sum += nums[right];            // 扩张
            // 满足条件就不断尝试收缩，找更短的
            while (sum >= target) {
                best = Math.min(best, right - left + 1);
                sum -= nums[left];
                left++;
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }
}
